// PRIMARY: ethereum/executionclient/.../EngineNewPayloadV4.java:execute (lines 49-80)
public SafeFuture<PayloadStatus> execute(final JsonRpcRequestParams params) {
    final ExecutionPayload executionPayload = params.getRequiredParameter(0, ExecutionPayload.class);
    final List<VersionedHash> blobVersionedHashes = params.getRequiredListParameter(1, VersionedHash.class);
    final Bytes32 parentBeaconBlockRoot = params.getRequiredParameter(2, Bytes32.class);
    final List<Bytes> executionRequests = params.getRequiredListParameter(3, Bytes.class);

    final ExecutionPayloadV3 executionPayloadV3 = ExecutionPayloadV3.fromInternalExecutionPayload(executionPayload);
    return executionEngineClient
        .newPayloadV4(executionPayloadV3, blobVersionedHashes, parentBeaconBlockRoot, executionRequests)
        .thenApply(ResponseUnwrapper::unwrapExecutionClientResponseOrThrow)
        .thenApply(PayloadStatusV1::asInternalExecutionPayload)
        .exceptionally(PayloadStatus::failedExecution);
}

